const MB = 1024 * 1024;
const sizeBytes = 50 * MB;

// Structured clone: deep copy on the sending thread, ~1 ms per MB.
const cloneBytesCopied = sizeBytes;
const cloneMs = (sizeBytes / MB) * 1; // ~1 ms/MB

// Transfer: ownership handoff, zero bytes copied, O(1).
const transferBytesCopied = 0;
const transferMs = 0; // microseconds, model as 0

const verdict = transferMs < cloneMs ? "transfer" : "clone";

console.log(`clone: copies ${cloneBytesCopied / MB} MB, blocks ~${cloneMs} ms`);
console.log(`transfer: copies ${transferBytesCopied / MB} MB, blocks ~${transferMs} ms`);
console.log(`verdict: use ${verdict} (saves ~${cloneMs - transferMs} ms)`);
